// IMAP engine for the native webmail client.
//
// Plain server-side module (NOT "use server"): it holds the short-lived imapflow
// connection helpers, special-use → role mapping, and the mailbox-ownership
// resolver shared by the server actions (lib/actions-mail.ts) and the attachment
// download route (app/api/mail/attachment/route.ts). Every connection is opened
// per-request and always closed. It is never imported into a client bundle.

import { ImapFlow } from "imapflow";
import type {
  FetchMessageObject,
  MailboxLockOptions,
  MessageAddressObject,
  MessageStructureObject,
} from "imapflow";
import { requireUser } from "@/lib/auth";
import { isStaff } from "@/lib/rbac";
import { hasAreaAccess } from "@/lib/staff-grants";
import { canAccessMailbox } from "@/lib/staff-mailbox-access";
import { db } from "@/lib/db";
import { decryptSecret } from "@/lib/crypto-box";
import { COMPANY_MAIL_DOMAIN } from "@/lib/company-mail-core";
import { checkRateLimit } from "@/lib/rate-limit";
import { mailcowConfigured, mcListMailboxes } from "@/lib/mailcow";
import { MAIL_IMAP_HOST, MAIL_IMAP_PORT, type MailAddress, type MailFolderRole } from "./types";
import type { User } from "@prisma/client";

// mailparser ships no bundled type declarations and its untyped JS module can't
// be augmented via `declare module`. Instead we describe the slice we use with
// local interfaces and import `simpleParser` with a suppressed-error import,
// exposing a single typed `parseMessage` wrapper for the rest of the backend.
// @ts-ignore -- mailparser has no type declarations
import { simpleParser as _simpleParser } from "mailparser";

export interface ParsedAttachment {
  type?: string;
  partId?: string;
  filename?: string;
  contentType?: string;
  contentDisposition?: string;
  size?: number;
  content?: Buffer;
  cid?: string;
  contentId?: string;
  related?: boolean;
}
export interface ParsedMessage {
  subject?: string;
  from?: { value?: { name?: string; address?: string }[]; text?: string };
  to?: unknown;
  cc?: unknown;
  bcc?: unknown;
  date?: Date;
  messageId?: string;
  inReplyTo?: string;
  references?: string | string[];
  html?: string | false;
  text?: string;
  textAsHtml?: string;
  attachments: ParsedAttachment[];
}

const simpleParser = _simpleParser as (
  source: Buffer | string,
  options?: Record<string, unknown>,
) => Promise<ParsedMessage>;

/** Parse a raw RFC822 message source into a typed structure (via mailparser). */
export async function parseMessage(source: Buffer | string): Promise<ParsedMessage> {
  return simpleParser(source);
}

/** The TLS servername the mail server's certificate is issued for. */
export const MAIL_TLS_SERVERNAME = process.env.MAIL_TLS_SERVERNAME || "mail.nxeon.cloud";

/**
 * TLS options for every webmail connection to the mail server (IMAP 993 and
 * SMTP submission 587). Shared so the two cannot drift apart.
 *
 * WHY VERIFICATION IS ON. We connect by internal IP (10.20.0.10) while the
 * server presents a public certificate for `mail.nxeon.cloud`, so a bare
 * connection fails on the name mismatch. The previous code resolved that by
 * setting `rejectUnauthorized: false` — which does not just tolerate the name
 * mismatch, it accepts ANY certificate from anything answering on that address.
 * The very first thing sent over that session is the customer's mailbox password
 * (IMAP LOGIN / SMTP AUTH), so anyone able to answer on the NAT bridge could
 * have harvested every mailbox credential on the platform, and nothing would
 * have looked wrong. `servername` alone is the correct fix: it sets SNI *and*
 * the name validation is performed against, so the real certificate verifies.
 *
 * MEASURED, not assumed (2026-07-27, from the app host):
 *   openssl s_client -connect 10.20.0.10:993 -servername mail.nxeon.cloud \
 *     -verify_return_error   ->  CN=mail.nxeon.cloud, "Verification: OK"
 *   …and the same on :587 with -starttls smtp.
 *
 * `MAIL_TLS_INSECURE=1` is a documented break-glass for an operator whose
 * certificate has genuinely expired mid-incident: it restores the old behaviour
 * from `.env` without a code change. It defaults OFF, so the safe state is the
 * one you get by doing nothing — the opposite of what it replaces.
 */
export function mailTlsOptions(): { servername: string; rejectUnauthorized: boolean } {
  return {
    servername: MAIL_TLS_SERVERNAME,
    rejectUnauthorized: process.env.MAIL_TLS_INSECURE !== "1",
  };
}

/** Minimal credential shape needed to authenticate an IMAP/SMTP session. */
export type MailboxCredentials = { address: string; password: string };

/** The sender identity the customer configured, applied to every outgoing message. */
export type MailboxIdentity = {
  displayName: string | null;
  replyTo: string | null;
  organization: string | null;
};

/** The subscription context a mailbox hangs off, for verification-aware guards. */
export type ResolvedSubscription = {
  id: string;
  domainName: string;
  external: boolean;
  verified: boolean;
  status: string;
};

/** A user mailbox row plus the decrypted credential, resolved + ownership-checked. */
export type ResolvedMailbox = {
  user: User;
  mailboxId: string;
  address: string;
  quotaMB: number | null;
  cred: MailboxCredentials;
  identity: MailboxIdentity;
  subscription: ResolvedSubscription;
};

/**
 * Adopt mailboxes that exist on Mailcow but have no local `Mailbox` row.
 *
 * WHY: `resolveMailbox` read ONLY `db.mailbox`, so a mailbox created directly on
 * the mail server — or one whose row was lost — was invisible in the portal even
 * though real mail was landing in it ("its not detecting the mailbox that i
 * already have on this account"). This reconciles the two.
 *
 * OWNERSHIP GUARD — the whole point of this function is that it MUST NOT become
 * a way to acquire someone else's mailbox:
 *   1. Only domains on a non-cancelled subscription owned by THIS user are read.
 *   2. Only subscriptions with `verified === true` are eligible. Owning a
