=== creator-outreach-send.ts ===
/**
 * REUSABLE operator script — sends the creator-sponsorship outreach email to a
 * CSV list of creators, one at a time, FROM a real CompanyMailbox (default:
 * santino@nxeon.cloud), with:
 *   - a genuine <ul><li> bulleted offer list (not flattened <br/> lines),
 *   - the mailbox's REAL stored signature (CompanyMailbox.signatureHtml — logo,
 *     name/title, links — exactly what appears when Santino sends by hand),
 *   - the same CAN-SPAM compliance footer as the rest of the platform's outreach
 *     (Brand.physicalPostalAddress + a one-line reply-to-unsubscribe notice),
 *   - a copy saved to the mailbox's Sent folder via IMAP APPEND, and
 *   - a real skip-list so a creator who already got THIS exact template is never
 *     double-emailed on a re-run.
 *
 * This is the general tool for future batches — do not fork a new one-off copy
 * per list. To send a new batch: drop a CSV with Name/Primary game/Email columns
 * (the same shape scripts/coldemail-creator-campaign-setup.ts's source CSV uses)
 * and run:
 *   npx tsx scripts/creator-outreach-send.ts --csv /path/to/list.csv
 *
 * Flags:
 *   --csv <path>       required. Columns: Name, Primary game, Email (others ignored).
 *   --from <address>   CompanyMailbox address to send from (default santino@nxeon.cloud).
 *   --min-ms / --max-ms  pacing window between sends in ms (default 5000/10000).
 *   --dry-run           render + log what WOULD send, no SMTP/IMAP calls.
 *
 * Every attempt (sent, failed, or skipped-as-duplicate) is appended as one JSON
 * line to <csv-dir>/send-log.jsonl next to the input CSV, keyed by lowercased
 * email — re-running the same CSV is safe and will not re-send to a logged
 * success.
 */
import { readFileSync, appendFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import nodemailer from "nodemailer";
import type { ImapFlow } from "imapflow";
import { db } from "../lib/db";
import { decryptSecret } from "../lib/crypto-box";
import { mailTlsOptions, withImap } from "../lib/mail/imap";

// ---------------------------------------------------------------------------
// CLI args
// ---------------------------------------------------------------------------
function argVal(flag: string, fallback?: string): string | undefined {
  const i = process.argv.indexOf(flag);
  return i !== -1 ? process.argv[i + 1] : fallback;
}
const CSV_PATH = argVal("--csv");
if (!CSV_PATH) {
  console.error("Usage: npx tsx scripts/creator-outreach-send.ts --csv <path> [--from email] [--min-ms N] [--max-ms N] [--dry-run]");
  process.exit(1);
}
const FROM_ADDRESS = argVal("--from", "santino@nxeon.cloud")!;
const MIN_MS = Number(argVal("--min-ms", "5000"));
const MAX_MS = Number(argVal("--max-ms", "10000"));
const DRY_RUN = process.argv.includes("--dry-run");
const LOG_PATH = join(dirname(CSV_PATH), "send-log.jsonl");
const MAIL_SMTP_HOST = process.env.MAIL_SMTP_HOST || "10.20.0.10";
const MAIL_SMTP_PORT = Number(process.env.MAIL_SMTP_PORT || 587);

// ---------------------------------------------------------------------------
// Template — same offer as the original 2026-09 creator blast (board card
// "test reachout" cmugx64kh00djhljsw2o7f1l0). {{firstName}}/{{game}} merge
// fields, OFFER_ITEMS rendered as a real bulleted list this time.
// ---------------------------------------------------------------------------
const SUBJECT_TMPL = "{{fullName}} × Nxeon — Sponsorship Offer";
const INTRO_MD = `Hey {{firstName}},

I'm Santino, founder of Nxeon, a Canadian cloud hosting company focused on game servers, VPS hosting, and developer infrastructure.

Nxeon supports 50+ different game titles, with {{game}} being one of our most popular. With 13 data centers across 4 continents, we're able to provide fast, reliable service to your viewers around the globe. We also offer 24/7 support and have built a community-driven mod library with 70,000+ mods and over 11.5 billion total downloads.

We've been steadily growing Nxeon and are now launching our creator partner program. I came across your content around {{game}} and really like what you're building, so I wanted to reach out and see if you'd be interested in working together.

For the launch of our creator program, we're offering a highly competitive founding partner offer that we don't expect to keep at this level permanently. We want to give the creators who join us early the strongest possible opportunity to benefit as Nxeon continues to grow.

Here's what we'd like to offer:`;

const OFFER_ITEMS = [
  "40% lifetime recurring commission on customers you refer",
  "50% off their first month for your audience",
  "10% off every month after through your personal creator code",
  "Your own Nxeon Partner Portal to track referrals, customers, renewals, commissions, and payouts",
  "Monthly commission payouts at the beginning of each month",
  "Your own referral link and creator code",
  "Promotional assets and direct support from our team",
];

const OUTRO_MD = `The 40% commission is lifetime, meaning you continue earning for as long as the customers you refer remain with Nxeon. If they purchase additional services in the future, you can earn from those as well.

This launch offer is specifically designed for our early creator partners. As the program grows, we expect future partnership terms to become more standardized, so joining during the launch gives you access to the most generous version of our creator program.

We're looking to build genuine, long-term relationships with creators rather than simply doing one-off sponsorships. As Nxeon continues to grow, we want our creators to grow alongside us.

If you're interested, I'd be happy to send over the full details and get you set up.

You can either email me here, or message me on WhatsApp for a faster response and direct support.`;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
function parseCsv(text: string): Record<string, string>[] {
  const lines = text.split(/\r?\n/).filter((l) => l.length > 0);
  const headers = lines[0].split(",");
  return lines.slice(1).map((line) => {
    const cells = line.split(",");
    const row: Record<string, string> = {};
    headers.forEach((h, i) => (row[h.trim()] = (cells[i] ?? "").trim()));
    return row;
  });
}

function firstNameOf(fullName: string): string {
  return fullName.trim().split(/\s+/)[0] || fullName.trim();
}

function fill(tmpl: string, vars: Record<string, string>): string {
  return tmpl.replace(/\{\{(\w+)\}\}/g, (_, k) => vars[k] ?? "");
}

function mdParagraphsToHtml(md: string): string {
  return md
    .split(/\n{2,}/)
    .map((p) => `<p style="margin:0 0 14px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.6;color:#222;">${p.split("\n").join("<br>")}</p>`)
    .join("\n");
}

function offerListHtml(items: string[]): string {
  const lis = items.map((it) => `<li style="margin:0 0 6px;">${it}</li>`).join("\n");
  return `<ul style="margin:0 0 14px;padding-left:22px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.6;color:#222;">\n${lis}\n</ul>`;
}

function offerListText(items: string[]): string {
  return items.map((it) => `- ${it}`).join("\n");
}

async function findSentPath(client: ImapFlow): Promise<string> {
  try {
    const list = await client.list();
    const sent = list.find((f) => f.specialUse === "\\Sent" || /sent/i.test(f.path));
    return sent?.path || "Sent";
  } catch {
    return "Sent";
  }
}

function sleep(ms: number) {
  return new Promise((r) => setTimeout(r, ms));
}

function loadSentSet(): Set<string> {
  const done = new Set<string>();
  if (!existsSync(LOG_PATH)) return done;
  for (const line of readFileSync(LOG_PATH, "utf8").split("\n")) {
    if (!line.trim()) continue;
    try {
      const e = JSON.parse(line);
      if (e.ok) done.add(String(e.email).toLowerCase());
    } catch {
      /* ignore malformed line */
    }
  }
  return done;
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------
async function main() {
  const mailbox = await db.companyMailbox.findUnique({ where: { address: FROM_ADDRESS } });
  if (!mailbox) throw new Error(`No CompanyMailbox row for ${FROM_ADDRESS}`);
  const password = decryptSecret(mailbox.passwordEnc);
  if (!password) throw new Error(`Could not decrypt password for ${FROM_ADDRESS} — reset it in /admin/mailboxes first.`);
  const displayName = mailbox.displayName || mailbox.label || "Santino";

  // The REAL signature (logo, name/title, links) exactly as it appears when
  // this mailbox sends by hand — not reconstructed from plain-text fields.
  const signatureHtml = mailbox.signatureHtml?.trim();
  if (!signatureHtml) throw new Error(`${FROM_ADDRESS} has no signatureHtml saved — set it in /admin/mailboxes first so sends match the real signature.`);
  const signatureText = (mailbox.signature || `${displayName}\nOwner, Nxeon\nnxeon.cloud | ${FROM_ADDRESS}`).trim();

  const brand = await db.brand.findFirst({ where: { name: "Nxeon" }, select: { name: true, physicalPostalAddress: true } });
  const postalAddress = brand?.physicalPostalAddress?.trim();
  if (!postalAddress) throw new Error("Brand 'Nxeon' has no physicalPostalAddress set — required for the compliance footer.");
  const footerHtml = `<p style="margin:24px 0 0;padding-top:16px;border-top:1px solid #e5e5e5;font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:1.6;color:#8a8a8a;">${brand!.name} · ${postalAddress}<br>Don't want these emails? Reply with "UNSUBSCRIBE" and we'll stop contacting you.</p>`;
  const footerText = `\n\n---\n${brand!.name} · ${postalAddress}\nDon't want these emails? Reply with "UNSUBSCRIBE" and we'll stop contacting you.`;

  const rows = parseCsv(readFileSync(CSV_PATH, "utf8"));
  const already = loadSentSet();
  console.log(`Loaded ${rows.length} recipients from ${CSV_PATH}. ${already.size} already logged as sent — those are skipped.`);
  console.log(`From: ${displayName} <${FROM_ADDRESS}>. Pacing: ${MIN_MS}-${MAX_MS}ms between sends.${DRY_RUN ? " DRY RUN — nothing will actually send." : ""}`);

  let smtp: nodemailer.Transporter | null = null;
  if (!DRY_RUN) {
    smtp = nodemailer.createTransport({
      host: MAIL_SMTP_HOST,
      port: MAIL_SMTP_PORT,
      secure: MAIL_SMTP_PORT === 465,
      requireTLS: MAIL_SMTP_PORT !== 465,
      tls: mailTlsOptions(),
      auth: { user: FROM_ADDRESS, pass: password },
    });
    await smtp.verify();
    console.log(`SMTP auth OK for ${FROM_ADDRESS} @ ${MAIL_SMTP_HOST}:${MAIL_SMTP_PORT}.`);
  }

  let sent = 0, failed = 0, skipped = 0;
  const toSend = rows.filter((r) => r["Email"] && !already.has(r["Email"].toLowerCase()));

  for (const [i, row] of toSend.entries()) {
    const fullName = row["Name"] || "there";
    const email = row["Email"];
    const game = row["Primary game"] || "your game";
    const vars = { fullName, firstName: firstNameOf(fullName), game };

    const subject = fill(SUBJECT_TMPL, vars);
    const introMd = fill(INTRO_MD, vars);
    const outroMd = fill(OUTRO_MD, vars);

    const html = [
      mdParagraphsToHtml(introMd),
      offerListHtml(OFFER_ITEMS),
      mdParagraphsToHtml(outroMd),
      `<div style="margin-top:22px;">${signatureHtml}</div>`,
      footerHtml,
    ].join("\n");
    const text = [introMd, offerListText(OFFER_ITEMS), outroMd, "", signatureText, footerText].join("\n\n");

    if (DRY_RUN) {
      console.log(`[${i + 1}/${toSend.length}] DRY -> ${email} (${fullName}, ${game}) subject="${subject}"`);
      continue;
    }

    try {
      const composer = nodemailer.createTransport({ streamTransport: true, buffer: true, newline: "\r\n" });
      const built = await composer.sendMail({ from: { name: displayName, address: FROM_ADDRESS }, to: email, subject, text, html });
      const raw = built.message as Buffer;

      const info = await smtp!.sendMail({ envelope: built.envelope, raw });
      sent++;

      try {
        await withImap({ address: FROM_ADDRESS, password }, async (client) => {
          const sentPath = await findSentPath(client);
          await client.append(sentPath, raw, ["\\Seen"]);
        });
      } catch (imapErr: unknown) {
        console.log(`  (Sent-folder copy failed, message still delivered: ${imapErr instanceof Error ? imapErr.message : imapErr})`);
      }

      appendFileSync(LOG_PATH, JSON.stringify({ email: email.toLowerCase(), name: fullName, game, ok: true, messageId: info.messageId, at: new Date().toISOString() }) + "\n");
      console.log(`[${i + 1}/${toSend.length}] SENT -> ${email} (${fullName}, ${game})`);
    } catch (err: unknown) {
      failed++;
      const msg = err instanceof Error ? err.message : String(err);
      appendFileSync(LOG_PATH, JSON.stringify({ email: email.toLowerCase(), name: fullName, game, ok: false, error: msg, at: new Date().toISOString() }) + "\n");
      console.log(`[${i + 1}/${toSend.length}] FAILED -> ${email}: ${msg}`);
    }

    if (i < toSend.length - 1) {
      await sleep(MIN_MS + Math.floor(Math.random() * Math.max(1, MAX_MS - MIN_MS)));
    }
  }

  skipped = rows.length - toSend.length;
  console.log(`\nDone. sent=${sent} failed=${failed} skipped(already sent)=${skipped} total_in_csv=${rows.length}`);
  await db.$disconnect();
}

main().catch(async (err) => {
  console.error("Send failed:", err?.message ?? err);
  await db.$disconnect().catch(() => null);
  process.exit(1);
});
