import { writeFileSync } from "node:fs";

type Rec = {
  uid: number;
  date: string;
  fromAddr: string;
  fromName: string;
  toAddr: string;
  toName: string;
  subject: string;
};

function addrOf(list: any): { address: string; name: string }[] {
  if (!list) return [];
  const arr = Array.isArray(list) ? list : list.value || [];
  return arr
    .map((a: any) => ({ address: (a.address || "").toLowerCase().trim(), name: a.name || "" }))
    .filter((a: any) => a.address);
}

async function findFolder(client: any, guesses: RegExp[], specialUse?: string) {
  const list = await client.list();
  for (const f of list) {
    if (specialUse && f.specialUse === specialUse) return f.path;
  }
  for (const g of guesses) {
    const hit = list.find((f: any) => g.test(f.path));
    if (hit) return hit.path;
  }
  return null;
}

async function main() {
  const mailbox = await db.companyMailbox.findUnique({ where: { address: "santino@nxeon.cloud" } });
  if (!mailbox) throw new Error("No CompanyMailbox row for santino@nxeon.cloud");
  const password = decryptSecret(mailbox.passwordEnc);
  if (!password) throw new Error("Could not decrypt password");

  const SUBJECT_RE = /×\s*Nxeon\s*—\s*Sponsorship Offer/i;

  const originals: Rec[] = [];
  const allSentOnSubject: Rec[] = []; // includes Re: replies Santino sent
  const inboxOnSubject: Rec[] = [];

  await withImap({ address: "santino@nxeon.cloud", password }, async (client) => {
    const sentPath = await findFolder(client, [/sent/i], "\\Sent");
    const inboxPath = await findFolder(client, [/^inbox$/i], "\\Inbox") || "INBOX";
    console.error("Sent path:", sentPath, "Inbox path:", inboxPath);

    // ---- SENT folder ----
    if (sentPath) {
      const lock = await client.getMailboxLock(sentPath, { readOnly: true });
      try {
        // Fetch envelope for ALL messages (subject filter client-side to catch
        // any encoding oddities), keep it light (no full body fetch needed for
        // matching — envelope has From/To/Subject/Date).
        for await (const msg of client.fetch("1:*", { envelope: true, uid: true })) {
          const subject = msg.envelope?.subject || "";
          if (!SUBJECT_RE.test(subject)) continue;
          const tos = addrOf(msg.envelope?.to);
          const froms = addrOf(msg.envelope?.from);
          const isReply = /^re:/i.test(subject.trim());
          for (const to of tos) {
            const rec: Rec = {
              uid: msg.uid,
              date: msg.envelope?.date ? new Date(msg.envelope.date).toISOString() : "",
              fromAddr: froms[0]?.address || "",
              fromName: froms[0]?.name || "",
              toAddr: to.address,
              toName: to.name,
              subject,
            };
            allSentOnSubject.push(rec);
            if (!isReply) originals.push(rec);
          }
        }
      } finally {
        lock.release();
      }
    }

    // ---- INBOX folder ----
    if (inboxPath) {
      const lock = await client.getMailboxLock(inboxPath, { readOnly: true });
      try {
        for await (const msg of client.fetch("1:*", { envelope: true, uid: true })) {
          const subject = msg.envelope?.subject || "";
          if (!SUBJECT_RE.test(subject)) continue;
          const froms = addrOf(msg.envelope?.from);
          for (const from of froms) {
            inboxOnSubject.push({
              uid: msg.uid,
              date: msg.envelope?.date ? new Date(msg.envelope.date).toISOString() : "",
              fromAddr: from.address,
              fromName: from.name,
              toAddr: "santino@nxeon.cloud",
              toName: "",
              subject,
            });
          }
        }
      } finally {
        lock.release();
      }
    }
  });

  // Dedup originals by recipient email, keep earliest send + name.
  const originalByEmail = new Map<string, Rec>();
  for (const r of originals) {
    const key = r.toAddr;
    const existing = originalByEmail.get(key);
    if (!existing || r.date < existing.date) originalByEmail.set(key, r);
  }

  // Recipients who replied: any INBOX message on this subject FROM them.
  const repliedEmails = new Set<string>();
  for (const r of inboxOnSubject) {
    repliedEmails.add(r.fromAddr);
  }

  const nonResponders: { email: string; name: string; sentDate: string }[] = [];
  const responders: { email: string; name: string }[] = [];
  for (const [email, rec] of originalByEmail.entries()) {
    if (repliedEmails.has(email)) {
      responders.push({ email, name: rec.toName });
    } else {
      nonResponders.push({ email, name: rec.toName, sentDate: rec.date });
    }
  }

  const result = {
    totalOriginalSentMessages: originals.length,
    totalUniqueRecipientsInSent: originalByEmail.size,
    totalInboxRepliesOnSubject: inboxOnSubject.length,
    totalUniqueRepliedEmails: repliedEmails.size,
    respondersCount: responders.length,
    nonRespondersCount: nonResponders.length,
    responders: responders.sort((a, b) => a.email.localeCompare(b.email)),
    nonResponders: nonResponders.sort((a, b) => a.email.localeCompare(b.email)),
    inboxRepliesRaw: inboxOnSubject,
  };

  writeFileSync(
    "/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/nonresponder-result.json",
    JSON.stringify(result, null, 2),
  );
  console.error("DONE. originals(unique)=", originalByEmail.size, "replied=", responders.length, "nonresponders=", nonResponders.length);

  await db.$disconnect();
}

main().catch(async (err) => {
  console.error("FAILED:", err?.message ?? err);
  await db.$disconnect().catch(() => null);
  process.exit(1);
});

